long input_value = 50000L;
int scale_factor = 3;
float tolerance = 0.99f;
const unsigned int THRESHOLD = 150000U;

if ( (unsigned int)(input_value * scale_factor) >
     (THRESHOLD + (unsigned int)((float)input_value * tolerance)) )
{
    // Casting (float)input_value ensures floating point multiplication
    // Outer casts enforce unsigned int comparison type
    input_value = 0L;
}
